use crate::position::AccountBalance;
use crate::reconcile::StatementPeriod;

/// The balances the STATEMENTS themselves assert.
///
/// A running-balance column is the institution stating what the account held when the period closed,
/// so a period's closing figure is an observation of exactly the kind a person supplies by typing
/// what the statement prints — arriving by a path that cannot mistype it. Deriving it is why
/// `bsc fin position` can answer at all from an export alone, instead of declaring an account and
/// then reporting that it has no balance.
///
/// The bounds arrive ALREADY SIGNED (`statement::period_from_running` converts at the boundary, for
/// `reconcile`'s sake), so nothing here converts. That is the one thing to know before editing this:
/// routing these through [`from_printed`] would negate every card balance a second time.
pub fn from_periods(periods: &[StatementPeriod]) -> Vec<AccountBalance> {
    periods
        .iter()
        .map(|p| AccountBalance { account: p.account.clone(), as_of: p.to.clone(), balance: p.closing })
        .collect()
}
